276   ConstraintInfo(const DataLayout &DL, ArrayRef<Value *> FunctionArgs)
277       : UnsignedCS(FunctionArgs), SignedCS(FunctionArgs), DL(DL) {
278     auto &Value2Index = getValue2Index(false);
