1236   SmallVector<Value *> Args;
1237   SmallPtrSet<Value *, 8> Seen;
1238   // Traverse Cond and its operands recursively until we reach a value that's in
1239   // Value2Index or not an instruction, or not a operation that
1240   // ConstraintElimination can decompose. Such values will be considered as
1241   // external inputs to the reproducer, they are collected and added as function
1242   // arguments later.
1243   auto CollectArguments = [&](ArrayRef<Value *> Ops, bool IsSigned) {
1244     auto &Value2Index = Info.getValue2Index(IsSigned);
1245     SmallVector<Value *, 4> WorkList(Ops);
1246     while (!WorkList.empty()) {
1247       Value *V = WorkList.pop_back_val();
1248       if (!Seen.insert(V).second)
1249         continue;
1250       if (Old2New.find(V) != Old2New.end())
1251         continue;
1252       if (isa<Constant>(V))
1253         continue;
1254 
1255       auto *I = dyn_cast<Instruction>(V);
1256       if (Value2Index.contains(V) || !I ||
1257           !isa<CmpInst, BinaryOperator, GEPOperator, CastInst>(V)) {
1258         Old2New[V] = V;
1259         Args.push_back(V);
1260         LLVM_DEBUG(dbgs() << "  found external input " << *V << "\n");
1261       } else {
1262         append_range(WorkList, I->operands());
1263       }
1264     }
1265   };
1266 
1267   for (auto &Entry : Stack)
1268     if (Entry.Pred != ICmpInst::BAD_ICMP_PREDICATE)
1269       CollectArguments({Entry.LHS, Entry.RHS}, ICmpInst::isSigned(Entry.Pred));
1270   CollectArguments(Cond, ICmpInst::isSigned(Cond->getPredicate()));
1271 
1272   SmallVector<Type *> ParamTys;
1273   for (auto *P : Args)
1274     ParamTys.push_back(P->getType());
1275 
1276   FunctionType *FTy = FunctionType::get(Cond->getType(), ParamTys,
1277                                         /*isVarArg=*/false);
1278   Function *F = Function::Create(FTy, Function::ExternalLinkage,
1279                                  Cond->getModule()->getName() +
1280                                      Cond->getFunction()->getName() + "repro",
1281                                  M);
1282   // Add arguments to the reproducer function for each external value collected.
1283   for (unsigned I = 0; I < Args.size(); ++I) {
1284     F->getArg(I)->setName(Args[I]->getName());
1285     Old2New[Args[I]] = F->getArg(I);
1286   }
1287 
1288   BasicBlock *Entry = BasicBlock::Create(Ctx, "entry", F);
1289   IRBuilder<> Builder(Entry);
1290   Builder.CreateRet(Builder.getTrue());
1291   Builder.SetInsertPoint(Entry->getTerminator());
1292 
1293   // Clone instructions in \p Ops and their operands recursively until reaching
1294   // an value in Value2Index (external input to the reproducer). Update Old2New
1295   // mapping for the original and cloned instructions. Sort instructions to
1296   // clone by dominance, then insert the cloned instructions in the function.
1297   auto CloneInstructions = [&](ArrayRef<Value *> Ops, bool IsSigned) {
1298     SmallVector<Value *, 4> WorkList(Ops);
1299     SmallVector<Instruction *> ToClone;
1300     auto &Value2Index = Info.getValue2Index(IsSigned);
1301     while (!WorkList.empty()) {
1302       Value *V = WorkList.pop_back_val();
1303       if (Old2New.find(V) != Old2New.end())
1304         continue;
1305 
1306       auto *I = dyn_cast<Instruction>(V);
1307       if (!Value2Index.contains(V) && I) {
1308         Old2New[V] = nullptr;
1309         ToClone.push_back(I);
1310         append_range(WorkList, I->operands());
1311       }
1312     }
1313 
1314     sort(ToClone,
1315          [&DT](Instruction *A, Instruction *B) { return DT.dominates(A, B); });
1316     for (Instruction *I : ToClone) {
1317       Instruction *Cloned = I->clone();
1318       Old2New[I] = Cloned;
1319       Old2New[I]->setName(I->getName());
1320       Cloned->insertBefore(&*Builder.GetInsertPoint());
1321       Cloned->dropUnknownNonDebugMetadata();
1322       Cloned->setDebugLoc({});
1323     }
1324   };
1325 
1326   // Materialize the assumptions for the reproducer using the entries in Stack.
1327   // That is, first clone the operands of the condition recursively until we
1328   // reach an external input to the reproducer and add them to the reproducer
1329   // function. Then add an ICmp for the condition (with the inverse predicate if
1330   // the entry is negated) and an assert using the ICmp.
1331   for (auto &Entry : Stack) {
1332     if (Entry.Pred == ICmpInst::BAD_ICMP_PREDICATE)
1333       continue;
1334 
1335     LLVM_DEBUG(dbgs() << "  Materializing assumption ";
1336                dumpUnpackedICmp(dbgs(), Entry.Pred, Entry.LHS, Entry.RHS);
1337                dbgs() << "\n");
1338     CloneInstructions({Entry.LHS, Entry.RHS}, CmpInst::isSigned(Entry.Pred));
1339 
1340     auto *Cmp = Builder.CreateICmp(Entry.Pred, Entry.LHS, Entry.RHS);
1341     Builder.CreateAssumption(Cmp);
1342   }
1343 
1344   // Finally, clone the condition to reproduce and remap instruction operands in
1345   // the reproducer using Old2New.
1346   CloneInstructions(Cond, CmpInst::isSigned(Cond->getPredicate()));
1347   Entry->getTerminator()->setOperand(0, Cond);
1348   remapInstructionsInBlocks({Entry}, Old2New);
1349 
1350   assert(!verifyFunction(*F, &dbgs()));
1351 }
