1467 /// Check if either the first condition of an AND or OR is implied by the
1468 /// (negated in case of OR) second condition or vice versa.
1469 static bool checkOrAndOpImpliedByOther(
1470     FactOrCheck &CB, ConstraintInfo &Info, Module *ReproducerModule,
1471     SmallVectorImpl<ReproducerEntry> &ReproducerCondStack,
1472     SmallVectorImpl<StackEntry> &DFSInStack) {
1473 
1474   CmpInst::Predicate Pred;
