1478   unsigned OtherOpIdx = JoinOp->getOperand(0) == CmpToCheck ? 1 : 0;
1479 
1480   // Don't try to simplify the first condition of a select by the second, as
1481   // this may make the select more poisonous than the original one.
1482   // TODO: check if the first operand may be poison.
1483   if (OtherOpIdx != 0 && isa<SelectInst>(JoinOp))
1484     return false;
1485 
1486   if (!match(JoinOp->getOperand(OtherOpIdx),
1487              m_ICmp(Pred, m_Value(A), m_Value(B))))
1488     return false;
1489 
1490   // For OR, check if the negated condition implies CmpToCheck.
1491   bool IsOr = match(JoinOp, m_LogicalOr());
1492   if (IsOr)
1493     Pred = CmpInst::getInversePredicate(Pred);
1494 
1495   // Optimistically add fact from first condition.
1496   unsigned OldSize = DFSInStack.size();
1497   Info.addFact(Pred, A, B, CB.NumIn, CB.NumOut, DFSInStack);
1498   if (OldSize == DFSInStack.size())
1499     return false;
1500 
1501   bool Changed = false;
1502   // Check if the second condition can be simplified now.
1503   if (auto ImpliedCondition =
1504           checkCondition(CmpToCheck->getPredicate(), CmpToCheck->getOperand(0),
1505                          CmpToCheck->getOperand(1), CmpToCheck, Info)) {
1506     if (IsOr && isa<SelectInst>(JoinOp)) {
1507       JoinOp->setOperand(
1508           OtherOpIdx == 0 ? 2 : 0,
1509           ConstantInt::getBool(JoinOp->getType(), *ImpliedCondition));
1510     } else
1511       JoinOp->setOperand(
1512           1 - OtherOpIdx,
1513           ConstantInt::getBool(JoinOp->getType(), *ImpliedCondition));
1514 
1515     Changed = true;
1516   }
1517 
1518   // Remove entries again.
1519   while (OldSize < DFSInStack.size()) {
1520     StackEntry E = DFSInStack.back();
1521     removeEntryFromStack(E, Info, ReproducerModule, ReproducerCondStack,
1522                          DFSInStack);
1523   }
1524   return Changed;
