1527 void ConstraintInfo::addFact(CmpInst::Predicate Pred, Value *A, Value *B,
1528                              unsigned NumIn, unsigned NumOut,
1529                              SmallVectorImpl<StackEntry> &DFSInStack) {
1530   // If the constraint has a pre-condition, skip the constraint if it does not
1531   // hold.
1532   SmallVector<Value *> NewVariables;
1533   auto R = getConstraint(Pred, A, B, NewVariables);
1534 
1535   // TODO: Support non-equality for facts as well.
1536   if (!R.isValid(*this) || R.isNe())
1537     return;
1538 
1539   LLVM_DEBUG(dbgs() << "Adding '"; dumpUnpackedICmp(dbgs(), Pred, A, B);
1540              dbgs() << "'\n");
1541   bool Added = false;
1542   auto &CSToUse = getCS(R.IsSigned);
1543   if (R.Coefficients.empty())
1544     return;
1545 
1546   Added |= CSToUse.addVariableRowFill(R.Coefficients);
1547 
1548   // If R has been added to the system, add the new variables and queue it for
1549   // removal once it goes out-of-scope.
1550   if (Added) {
1551     SmallVector<Value *, 2> ValuesToRelease;
1552     auto &Value2Index = getValue2Index(R.IsSigned);
1553     for (Value *V : NewVariables) {
1554       Value2Index.insert({V, Value2Index.size() + 1});
1555       ValuesToRelease.push_back(V);
1556     }
1557 
1558     LLVM_DEBUG({
1559       dbgs() << "  constraint: ";
1560       dumpConstraint(R.Coefficients, getValue2Index(R.IsSigned));
1561       dbgs() << "\n";
1562     });
1563 
1564     DFSInStack.emplace_back(NumIn, NumOut, R.IsSigned,
1565                             std::move(ValuesToRelease));
1566 
1567     if (!R.IsSigned) {
1568       for (Value *V : NewVariables) {
1569         ConstraintTy VarPos(SmallVector<int64_t, 8>(Value2Index.size() + 1, 0),
1570                             false, false, false);
1571         VarPos.Coefficients[Value2Index[V]] = -1;
1572         CSToUse.addVariableRow(VarPos.Coefficients);
1573         DFSInStack.emplace_back(NumIn, NumOut, R.IsSigned,
1574                                 SmallVector<Value *, 2>());
1575       }
1576     }
1577 
1578     if (R.isEq()) {
1579       // Also add the inverted constraint for equality constraints.
1580       for (auto &Coeff : R.Coefficients)
1581         Coeff *= -1;
1582       CSToUse.addVariableRowFill(R.Coefficients);
1583 
1584       DFSInStack.emplace_back(NumIn, NumOut, R.IsSigned,
1585                               SmallVector<Value *, 2>());
1586     }
1587   }
